package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments allows full-text search across documents
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("class")

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	// Basic length check
	if len(query) > 200 {
		http.Error(w, "Query too long", 400)
		return
	}

	// Build search query with classification filter
	var sqlQuery string
	if classification != "" {
		// NOTE: classification is validated against enum in the DB constraint
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, content, owner_id, classification FROM documents WHERE classification = '%s' AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1)",
			classification,
		)
	} else {
		sqlQuery = "SELECT id, title, content, owner_id, classification FROM documents WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1)"
	}

	rows, err := db.Query(sqlQuery, query)
	if err != nil {
		log.Printf("Search error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// getDocument retrieves a single document by ID (parameterized, safe)
func getDocument(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/api/documents/")
	var d Document
	err := db.QueryRow(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE id = $1", id,
	).Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(d)
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/api/documents/", getDocument)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
